package com.drogaria.backend.dto;
import jakarta.validation.constraints.NotBlank; import jakarta.validation.constraints.NotNull; import java.time.LocalDate;
public class LoteRequest { @NotBlank private String numeroLote; @NotNull private LocalDate dataFabricacao; @NotNull private LocalDate dataValidade; @NotNull private Integer quantidade; @NotNull private Integer idEstoque; public String getNumeroLote(){return numeroLote;} public void setNumeroLote(String v){numeroLote=v;} public LocalDate getDataFabricacao(){return dataFabricacao;} public void setDataFabricacao(LocalDate v){dataFabricacao=v;} public LocalDate getDataValidade(){return dataValidade;} public void setDataValidade(LocalDate v){dataValidade=v;} public Integer getQuantidade(){return quantidade;} public void setQuantidade(Integer v){quantidade=v;} public Integer getIdEstoque(){return idEstoque;} public void setIdEstoque(Integer v){idEstoque=v;} }